-- READ-ONLY exact-key aggregate; excludes protected Q1 2018; UTC bounds.
WITH c AS (SELECT CASE WHEN o.dateTime<1530403200 THEN '2018-Q2' WHEN o.dateTime<1538352000 THEN '2018-Q3' ELSE '2018-Q4' END AS utc_quarter,o.usUnits AS ou,w.usUnits AS wu,o.interval AS oi,w.interval AS wi,o.`leafTemp1` AS old_leafTemp1, w.`leafTemp1` AS wh_leafTemp1, o.`leafTemp2` AS old_leafTemp2, w.`leafTemp2` AS wh_leafTemp2, o.`leafWet1` AS old_leafWet1, w.`leafWet1` AS wh_leafWet1, o.`leafWet2` AS old_leafWet2, w.`leafWet2` AS wh_leafWet2, o.`outHumidity` AS old_outHumidity, w.`outHumidity` AS wh_outHumidity, o.`outTemp` AS old_outTemp, w.`outTemp` AS wh_outTemp, o.`outTempBatteryStatus` AS old_outTempBatteryStatus, w.`outTempBatteryStatus` AS wh_outTempBatteryStatus, o.`pressure` AS old_pressure, w.`pressure` AS wh_pressure, o.`radiation` AS old_radiation, w.`radiation` AS wh_radiation, o.`rain` AS old_rain, w.`rain` AS wh_rain FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1522540800 AND o.dateTime<1546300800 AND r.dateTime IS NULL) SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'leafTemp1' AS field_name,COUNT(*) AS source_only_rows,SUM(old_leafTemp1 IS NOT NULL) AS old_nonnull,SUM(wh_leafTemp1 IS NOT NULL) AS wh_nonnull,SUM(old_leafTemp1 IS NOT NULL AND wh_leafTemp1 IS NOT NULL AND old_leafTemp1<=>wh_leafTemp1) AS paired_equal,SUM(old_leafTemp1 IS NOT NULL AND wh_leafTemp1 IS NOT NULL AND NOT(old_leafTemp1<=>wh_leafTemp1)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'leafTemp2' AS field_name,COUNT(*) AS source_only_rows,SUM(old_leafTemp2 IS NOT NULL) AS old_nonnull,SUM(wh_leafTemp2 IS NOT NULL) AS wh_nonnull,SUM(old_leafTemp2 IS NOT NULL AND wh_leafTemp2 IS NOT NULL AND old_leafTemp2<=>wh_leafTemp2) AS paired_equal,SUM(old_leafTemp2 IS NOT NULL AND wh_leafTemp2 IS NOT NULL AND NOT(old_leafTemp2<=>wh_leafTemp2)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'leafWet1' AS field_name,COUNT(*) AS source_only_rows,SUM(old_leafWet1 IS NOT NULL) AS old_nonnull,SUM(wh_leafWet1 IS NOT NULL) AS wh_nonnull,SUM(old_leafWet1 IS NOT NULL AND wh_leafWet1 IS NOT NULL AND old_leafWet1<=>wh_leafWet1) AS paired_equal,SUM(old_leafWet1 IS NOT NULL AND wh_leafWet1 IS NOT NULL AND NOT(old_leafWet1<=>wh_leafWet1)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'leafWet2' AS field_name,COUNT(*) AS source_only_rows,SUM(old_leafWet2 IS NOT NULL) AS old_nonnull,SUM(wh_leafWet2 IS NOT NULL) AS wh_nonnull,SUM(old_leafWet2 IS NOT NULL AND wh_leafWet2 IS NOT NULL AND old_leafWet2<=>wh_leafWet2) AS paired_equal,SUM(old_leafWet2 IS NOT NULL AND wh_leafWet2 IS NOT NULL AND NOT(old_leafWet2<=>wh_leafWet2)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'outHumidity' AS field_name,COUNT(*) AS source_only_rows,SUM(old_outHumidity IS NOT NULL) AS old_nonnull,SUM(wh_outHumidity IS NOT NULL) AS wh_nonnull,SUM(old_outHumidity IS NOT NULL AND wh_outHumidity IS NOT NULL AND old_outHumidity<=>wh_outHumidity) AS paired_equal,SUM(old_outHumidity IS NOT NULL AND wh_outHumidity IS NOT NULL AND NOT(old_outHumidity<=>wh_outHumidity)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'outTemp' AS field_name,COUNT(*) AS source_only_rows,SUM(old_outTemp IS NOT NULL) AS old_nonnull,SUM(wh_outTemp IS NOT NULL) AS wh_nonnull,SUM(old_outTemp IS NOT NULL AND wh_outTemp IS NOT NULL AND old_outTemp<=>wh_outTemp) AS paired_equal,SUM(old_outTemp IS NOT NULL AND wh_outTemp IS NOT NULL AND NOT(old_outTemp<=>wh_outTemp)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'outTempBatteryStatus' AS field_name,COUNT(*) AS source_only_rows,SUM(old_outTempBatteryStatus IS NOT NULL) AS old_nonnull,SUM(wh_outTempBatteryStatus IS NOT NULL) AS wh_nonnull,SUM(old_outTempBatteryStatus IS NOT NULL AND wh_outTempBatteryStatus IS NOT NULL AND old_outTempBatteryStatus<=>wh_outTempBatteryStatus) AS paired_equal,SUM(old_outTempBatteryStatus IS NOT NULL AND wh_outTempBatteryStatus IS NOT NULL AND NOT(old_outTempBatteryStatus<=>wh_outTempBatteryStatus)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'pressure' AS field_name,COUNT(*) AS source_only_rows,SUM(old_pressure IS NOT NULL) AS old_nonnull,SUM(wh_pressure IS NOT NULL) AS wh_nonnull,SUM(old_pressure IS NOT NULL AND wh_pressure IS NOT NULL AND old_pressure<=>wh_pressure) AS paired_equal,SUM(old_pressure IS NOT NULL AND wh_pressure IS NOT NULL AND NOT(old_pressure<=>wh_pressure)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'radiation' AS field_name,COUNT(*) AS source_only_rows,SUM(old_radiation IS NOT NULL) AS old_nonnull,SUM(wh_radiation IS NOT NULL) AS wh_nonnull,SUM(old_radiation IS NOT NULL AND wh_radiation IS NOT NULL AND old_radiation<=>wh_radiation) AS paired_equal,SUM(old_radiation IS NOT NULL AND wh_radiation IS NOT NULL AND NOT(old_radiation<=>wh_radiation)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'rain' AS field_name,COUNT(*) AS source_only_rows,SUM(old_rain IS NOT NULL) AS old_nonnull,SUM(wh_rain IS NOT NULL) AS wh_nonnull,SUM(old_rain IS NOT NULL AND wh_rain IS NOT NULL AND old_rain<=>wh_rain) AS paired_equal,SUM(old_rain IS NOT NULL AND wh_rain IS NOT NULL AND NOT(old_rain<=>wh_rain)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi
ORDER BY utc_quarter,old_interval,wh_interval,field_name\n